40: func newJWTHelper(ctx context.Context, conf *JWTConf) *jwtHelper {
41: 	jh := &jwtHelper{verify: true}
42: 
43: 	if conf == nil {
44: 		return jh
45: 	}
46: 
47: 	jh.verify = !conf.DisableVerification
48: 	jh.acceptableSkew = conf.AcceptableTimeSkew
49: 
50: 	if jh.verify {
51: 		log := logging.FromContext(ctx).Named("auxdata")
52: 		jh.keySets = make(map[string]keySet, len(conf.KeySets))
53: 
54: 		var jwkCache *jwk.Cache
55: 		for _, ks := range conf.KeySets {
56: 			var opts []any
57: 			if ks.Insecure.OptionalAlg {
58: 				log.Warn("[INSECURE CONFIG] Enabling optional alg field for key set", zap.String("keySetID", ks.ID))
59: 				opts = append(opts, jws.WithInferAlgorithmFromKey(true))
60: 			}
61: 
62: 			if ks.Insecure.OptionalKid {
63: 				log.Warn("[INSECURE CONFIG] Enabling optional kid field for key set", zap.String("keySetID", ks.ID))
64: 				opts = append(opts, jws.WithRequireKid(false))
65: 			}
66: 
67: 			switch {
68: 			case ks.Remote != nil:
69: 				if jwkCache == nil {
70: 					jwkCache = newJWKCache(ctx, log)
71: 				}
72: 				jh.keySets[ks.ID] = newRemoteKeySet(ctx, jwkCache, ks.Remote, &ks.Insecure, opts)
73: 			case ks.Local != nil:
74: 				jh.keySets[ks.ID] = newLocalKeySet(ks.Local, &ks.Insecure, opts)
75: 			}
76: 		}
77: 	}
78: 
79: 	return jh
80: }
