82: func newJWKCache(ctx context.Context, log *zap.Logger) *jwk.Cache {
83: 	jwkCache, err := jwk.NewCache(ctx, httprc.NewClient(httprc.WithErrorSink(jwkErrSink{log: log})))
84: 	if err != nil {
85: 		// this should never happen; jwk.NewCache only returns an error if you pass it an httprc.Client that has already been started.
86: 		panic(fmt.Errorf("failed to create JWK cache: %w", err))
87: 	}
88: 	return jwkCache
89: }
