99: func (j *jwtHelper) extract(ctx context.Context, auxJWT *requestv1.AuxData_JWT) (map[string]*structpb.Value, error) {
100: 	if auxJWT == nil || auxJWT.Token == "" {
101: 		return nil, nil
102: 	}
103: 
104: 	ctx, span := tracing.StartSpan(ctx, "aux_data.ExtractJWT")
105: 	defer span.End()
106: 
107: 	parseOpts, err := j.parseOptions(ctx, auxJWT)
108: 	if err != nil {
109: 		return nil, err
110: 	}
111: 
112: 	return j.doExtract(ctx, auxJWT, parseOpts)
