115: func (j *jwtHelper) parseOptions(ctx context.Context, auxJWT *requestv1.AuxData_JWT) (opts []jwt.ParseOption, _ error) {
116: 	if j.acceptableSkew > 0 {
117: 		opts = []jwt.ParseOption{jwt.WithAcceptableSkew(j.acceptableSkew)}
118: 	}
119: 
120: 	if !j.verify {
121: 		return append(opts, jwt.WithVerify(false), jwt.WithValidate(true)), nil
122: 	}
123: 
124: 	var ks keySet
125: 	// if keyset ID is not provided and we only have one keyset configured, use that as the default.
126: 	if auxJWT.KeySetId == "" {
127: 		if len(j.keySets) != 1 {
128: 			return nil, errNoKeySetToVerify
129: 		}
130: 
131: 		for _, ksDef := range j.keySets {
132: 			ks = ksDef
133: 		}
134: 	} else { // use the keyset specified in the request
135: 		ksDef, ok := j.keySets[auxJWT.KeySetId]
136: 		if !ok {
137: 			return nil, fmt.Errorf("keyset not found: %s", auxJWT.KeySetId)
138: 		}
139: 		ks = ksDef
140: 	}
141: 
142: 	jwks, jwksOpts, err := ks.keySet(ctx)
143: 	if err != nil {
144: 		return nil, fmt.Errorf("failed to retrieve keyset: %w", err)
145: 	}
146: 
147: 	return append(opts, jwt.WithKeySet(jwks, jwksOpts...), jwt.WithValidate(true)), nil
148: }
